"""URL shortener REST API backed by SQLite."""
import secrets
import sqlite3
import string
from urllib.parse import urlparse

from flask import Flask, g, jsonify, redirect, request

ALPHABET = string.ascii_letters + string.digits
CODE_LEN = 7


def create_app(db_path=":memory:"):
    app = Flask(__name__)
    app.config["DB_PATH"] = db_path

    def get_db():
        if "db" not in g:
            g.db = sqlite3.connect(app.config["DB_PATH"])
            g.db.row_factory = sqlite3.Row
            g.db.execute(
                """CREATE TABLE IF NOT EXISTS urls (
                    code TEXT PRIMARY KEY,
                    url TEXT NOT NULL,
                    hits INTEGER NOT NULL DEFAULT 0
                )"""
            )
        return g.db

    @app.teardown_appcontext
    def close_db(_exc):
        db = g.pop("db", None)
        if db is not None:
            db.close()

    def valid_url(url):
        try:
            p = urlparse(url)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except ValueError:
            return False

    @app.post("/api/shorten")
    def shorten():
        data = request.get_json(silent=True) or {}
        url = data.get("url", "")
        if not valid_url(url):
            return jsonify(error="invalid or missing 'url' (must be http/https)"), 400

        db = get_db()
        custom = data.get("code")
        if custom is not None:
            if not (1 <= len(custom) <= 32 and all(c in ALPHABET for c in custom)):
                return jsonify(error="custom code must be 1-32 alphanumeric chars"), 400
            try:
                db.execute("INSERT INTO urls (code, url) VALUES (?, ?)", (custom, url))
            except sqlite3.IntegrityError:
                return jsonify(error="code already in use"), 409
            code = custom
        else:
            while True:
                code = "".join(secrets.choice(ALPHABET) for _ in range(CODE_LEN))
                try:
                    db.execute("INSERT INTO urls (code, url) VALUES (?, ?)", (code, url))
                    break
                except sqlite3.IntegrityError:
                    continue
        db.commit()
        return jsonify(code=code, url=url, short_url=f"{request.host_url}{code}"), 201

    @app.get("/<code>")
    def follow(code):
        db = get_db()
        row = db.execute("SELECT url FROM urls WHERE code = ?", (code,)).fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        db.execute("UPDATE urls SET hits = hits + 1 WHERE code = ?", (code,))
        db.commit()
        return redirect(row["url"], code=302)

    @app.get("/api/urls/<code>")
    def stats(code):
        row = get_db().execute(
            "SELECT code, url, hits FROM urls WHERE code = ?", (code,)
        ).fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        return jsonify(dict(row))

    @app.delete("/api/urls/<code>")
    def delete(code):
        db = get_db()
        cur = db.execute("DELETE FROM urls WHERE code = ?", (code,))
        db.commit()
        if cur.rowcount == 0:
            return jsonify(error="not found"), 404
        return "", 204

    return app


if __name__ == "__main__":
    create_app("urls.db").run(debug=True)

import pytest

from app import create_app


@pytest.fixture()
def client(tmp_path):
    app = create_app(str(tmp_path / "test.db"))
    app.testing = True
    with app.test_client() as c:
        yield c


def shorten(client, **payload):
    return client.post("/api/shorten", json=payload)


def test_shorten_returns_code(client):
    r = shorten(client, url="https://example.com/page")
    assert r.status_code == 201
    body = r.get_json()
    assert len(body["code"]) == 7
    assert body["short_url"].endswith(body["code"])


def test_redirect_follows_and_counts(client):
    code = shorten(client, url="https://example.com").get_json()["code"]
    r = client.get(f"/{code}")
    assert r.status_code == 302
    assert r.headers["Location"] == "https://example.com"
    assert client.get(f"/api/urls/{code}").get_json()["hits"] == 1


def test_custom_code(client):
    r = shorten(client, url="https://example.com", code="mylink")
    assert r.status_code == 201
    assert r.get_json()["code"] == "mylink"


def test_custom_code_conflict(client):
    shorten(client, url="https://example.com", code="dup")
    assert shorten(client, url="https://other.com", code="dup").status_code == 409


@pytest.mark.parametrize("payload", [{}, {"url": "notaurl"}, {"url": "ftp://x.com"}])
def test_invalid_url_rejected(client, payload):
    assert shorten(client, **payload).status_code == 400


def test_invalid_custom_code_rejected(client):
    assert shorten(client, url="https://example.com", code="bad code!").status_code == 400


def test_unknown_code_404(client):
    assert client.get("/nope999").status_code == 404
    assert client.get("/api/urls/nope999").status_code == 404


def test_delete(client):
    code = shorten(client, url="https://example.com").get_json()["code"]
    assert client.delete(f"/api/urls/{code}").status_code == 204
    assert client.get(f"/{code}").status_code == 404
    assert client.delete(f"/api/urls/{code}").status_code == 404
